#define WHEEL_SIZE 256
struct SleepRef* wheel[WHEEL_SIZE];
int current_tick = 0;
```

```c
void add_sleep(int ticks_from_now, int thread){
  int t = (current_tick + ticks_from_now) % WHEEL_SIZE;
  lock_bucket(t);
  insert_tail(&wheel[t], thread);
  unlock_bucket(t);
}
```

```c
void tick_handler(void){
  current_tick = (current_tick + 1) % WHEEL_SIZE;
  int idx = current_tick % WHEEL_SIZE;
  lock_bucket(idx);
  wake_all_in_bucket(wheel[idx]);
  wheel[idx] = NULL;
  unlock_bucket(idx);
}
```

